CMP = ("lang", "cost", "funds", "tests", "work", "after", "schol")

def body(i, tabs_html, nxt):
    cards = ""
    for c in C:
        rows = "".join(f'<div class="trow"><span>{X["r_" + k][i]}</span><b class="fv">{v[i]}</b></div>' for k, v in c["rows"].items())
        cards += (f'<details class="uni card cc" data-lang="{c["lang"]}" data-cost="{c["tier"]}" data-schol="{c["schol"]}"><summary><span class="flag">{c["flag"]}</span>'
                  f'<span class="uname"><b>{c["name"][i]}</b><small>{c["tag"][i]}</small></span><span class="tier" title="{X["tier_h"][i]}">{"$" * c["tier"]}<i>{"$" * (3 - c["tier"])}</i></span></summary>'
                  f'<div class="ubody">{rows}<a class="uofficial" href="{c["url"]}" rel="noopener">{X["official"][i]}</a></div></details>')
    def chips(g, opts):
        return f'<div class="fgroup" data-g="{g}"><h4>{X["q_" + g][i]}</h4><div class="fchips">' + "".join(
            f'<button type="button" class="fc{" on" if n == 0 else ""}" data-v="{v}">{X[t][i]}</button>' for n, (v, t) in enumerate(opts)) + '</div></div>'
    finder = (f'<div class="card finder">{chips("lang", [("all", "l_all"), ("en", "l_en")])}'
              f'{chips("cost", [("all", "c_all"), ("1", "c_low"), ("2", "c_mid")])}{chips("schol", [("all", "s_all"), ("gov", "s_gov")])}'
              f'<p class="fcount" id="fcount" aria-live="polite"></p></div>')
    head = "".join(f"<th>{X['r_' + k][i]}</th>" for k in CMP)
    trs = "".join(f'<tr><th scope="row">{c["flag"]} {c["name"][i]}</th>' + "".join(f"<td>{c['rows'][k][i] if k in c['rows'] else '—'}</td>" for k in CMP) + "</tr>" for c in C)
    table = f'<h3 class="cmph">{X["cmp_h"][i]}</h3><div class="cmpw"><table class="cmp"><thead><tr><th></th>{head}</tr></thead><tbody>{trs}</tbody></table></div>'
    js = ("<script>(function(){var G={lang:'all',cost:'all',schol:'all'},N=document.getElementById('fcount'),T=" + repr(X["found"][i]) + ",Z=" + repr(X["none"][i]) + ";"
          "function run(){var n=0;document.querySelectorAll('.cc').forEach(function(c){var l=c.dataset.lang,ok=true;"
          "if(G.lang=='en'&&l=='local')ok=false;if(G.cost!='all'&&+c.dataset.cost>+G.cost)ok=false;if(G.schol=='gov'&&c.dataset.schol!='gov')ok=false;"
          "c.hidden=!ok;if(ok)n++});N.textContent=n?T.replace('{n}',n):Z}"
          "document.querySelectorAll('.fgroup').forEach(function(g){g.addEventListener('click',function(e){var b=e.target.closest('.fc');if(!b)return;"
          "g.querySelectorAll('.fc').forEach(function(x){x.classList.toggle('on',x==b)});G[g.dataset.g]=b.dataset.v;run()})});run()})()</script>")
    return (f'{tabs_html}<p class="lead2">{X["intro"][i]}</p>{finder}<p class="note">{X["tier"][i]}</p><div class="unis">{cards}</div>'
            f'<p class="note">{X["visa"][i]}</p>{table}<p class="note">{X["warn"][i]}</p>{nxt}{js}')
